insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('comparando-distintos-formatos-educativos-para-publico-infantil','educacion',array['arte']::text[],'Comparando distintos formatos educativos para público infantil','Compara cómo aprenden niñas y niños un mismo tema con formatos distintos, como cuento, juego, video o experimento, y observa cuál capta más su atención y deja más aprendizaje.','Investigación','3 a 4 semanas',22,array['Formatos','Educación infantil']::text[],array['investigar']::text[],'ficticios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion diseno de materiales. observacion. comparacion. comunicacion. materiales de cada formato. una hoja de observacion. hoja de calculo.',$a53sld${"id": "comparando-distintos-formatos-educativos-para-publico-infantil", "area": "educacion", "areas2": ["arte"], "titulo": "Comparando distintos formatos educativos para público infantil", "resumen": "Compara cómo aprenden niñas y niños un mismo tema con formatos distintos, como cuento, juego, video o experimento, y observa cuál capta más su atención y deja más aprendizaje.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 22, "etiquetas": ["Formatos", "Educación infantil"], "intencion": ["investigar"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Se usan muchos formatos para enseñar a los niños, pero no siempre se sabe cuál funciona mejor para cada tema. Un formato divertido puede entretener sin enseñar, y uno serio puede aburrir.", "Comparar formatos con un mismo contenido da pistas para elegir bien."], "desarrollar": ["Elige un tema sencillo y prepara tres formatos: un cuento, un juego y un video corto. Con autorización y acompañamiento de adultos, presenta cada formato a un grupo distinto de niñas y niños de la misma edad.", "Evalúa con preguntas sencillas qué recuerdan y entienden, observa la atención durante la actividad y compara los resultados. Resume qué formato conviene según el tipo de tema."], "ampliaciones": [{"titulo": "Por edades", "aporta": "compara resultados entre dos edades."}, {"titulo": "Combinación", "aporta": "prueba combinar dos formatos."}, {"titulo": "Opinión de las familias", "aporta": "recoge la percepción de madres, padres o docentes."}], "objetivos": ["Preparar tres formatos.", "Aplicarlos con autorización.", "Evaluar atención y aprendizaje.", "Resumir conclusiones."], "habilidades": ["Diseño de materiales.", "Observación.", "Comparación.", "Comunicación."], "herramientas": ["Materiales de cada formato.", "Una hoja de observación.", "Hoja de cálculo."], "lineamientos": ["Si pruebas el material con niñas y niños, hazlo con autorización de su familia o de la institución, sin fotos ni datos personales, y con un adulto presente.", "Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Los resultados con pocos niños son orientativos, no definitivos."], "otroSector": "La misma comparación sirve para elegir formatos de capacitación para adultos."}$a53sld$::jsonb,60),
('comparando-distintas-formas-de-usar-videos-educativos-para-apren','educacion',array['tecnologia']::text[],'Comparando distintas formas de usar videos educativos para aprender un tema','Compara formas de aprender con videos, como verlos de corrido, pausarlos, tomar apuntes o hacer ejercicios después, y mide cuál te deja más aprendizaje y cómo complementarlos con otras actividades.','Investigación','3 semanas',22,array['Videos educativos','Aprendizaje']::text[],array['investigar','resolver']::text[],'propios',NULL,'educacion ingenieria de sistemas ciencia de datos psicologia comunicaciones estadistica diseno administracion diseno de experimentos. autoobservacion. analisis simple de datos. redaccion. videos educativos gratuitos. hoja de calculo. pruebas cortas propias.',$a54sld${"id": "comparando-distintas-formas-de-usar-videos-educativos-para-apren", "area": "educacion", "areas2": ["tecnologia"], "titulo": "Comparando distintas formas de usar videos educativos para aprender un tema", "resumen": "Compara formas de aprender con videos, como verlos de corrido, pausarlos, tomar apuntes o hacer ejercicios después, y mide cuál te deja más aprendizaje y cómo complementarlos con otras actividades.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Videos educativos", "Aprendizaje"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Ingeniería de Sistemas", "Ciencia de Datos", "Psicología", "Comunicaciones", "Estadística", "Diseño", "Administración"], "problema": ["Se ven muchos videos para estudiar, pero a menudo se miran de forma pasiva y se olvidan pronto. No es lo mismo ver un video de corrido que pausarlo, anotar y practicar luego.", "Probar formas de usarlos permite aprovechar mejor esas horas."], "desarrollar": ["Elige un tema con varios videos de buena calidad y estudia cuatro partes con formas distintas: verlo sin pausas, verlo con pausas y apuntes, verlo y luego explicar de memoria, y verlo con ejercicios después.", "Evalúa con una prueba corta una semana después, compara los resultados y el tiempo invertido y arma una recomendación de cómo usar videos para estudiar."], "ampliaciones": [{"titulo": "Velocidad de reproducción", "aporta": "compara ver a velocidad normal y acelerada."}, {"titulo": "Videos largos y cortos", "aporta": "compara videos de distinta duración."}, {"titulo": "Video más lectura", "aporta": "prueba combinar con un texto."}], "objetivos": ["Comparar formas de usar videos.", "Medir aprendizaje y tiempo.", "Comprobar el efecto de la práctica posterior.", "Recomendar un método."], "habilidades": ["Diseño de experimentos.", "Autoobservación.", "Análisis simple de datos.", "Redacción."], "herramientas": ["Videos educativos gratuitos.", "Hoja de cálculo.", "Pruebas cortas propias."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Usa herramientas que ya existan y cuyas condiciones de uso respetes; no subas datos de otras personas a plataformas sin su permiso.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión."], "otroSector": "La misma comparación sirve para elegir formatos de capacitación en video en una empresa."}$a54sld$::jsonb,61),
('los-cuestionarios-digitales-ayudan-a-aprender-o-solo-a-comprobar','educacion',array['tecnologia']::text[],'¿Los cuestionarios digitales ayudan a aprender o solo a comprobar lo que recordamos?','Prueba si hacer cuestionarios digitales con retroalimentación inmediata ayuda a aprender más que solo estudiar, y qué tipo de preguntas dejan más aprendizaje.','Investigación','3 semanas',22,array['Cuestionarios','Evaluación formativa']::text[],array['investigar']::text[],'propios',NULL,'educacion ingenieria de sistemas ciencia de datos psicologia comunicaciones estadistica diseno administracion diseno de pruebas. analisis de datos. pensamiento critico. redaccion. una herramienta de cuestionarios ya existente. hoja de calculo. material de estudio.',$a55sld${"id": "los-cuestionarios-digitales-ayudan-a-aprender-o-solo-a-comprobar", "area": "educacion", "areas2": ["tecnologia"], "titulo": "¿Los cuestionarios digitales ayudan a aprender o solo a comprobar lo que recordamos?", "resumen": "Prueba si hacer cuestionarios digitales con retroalimentación inmediata ayuda a aprender más que solo estudiar, y qué tipo de preguntas dejan más aprendizaje.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Cuestionarios", "Evaluación formativa"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Ingeniería de Sistemas", "Ciencia de Datos", "Psicología", "Comunicaciones", "Estadística", "Diseño", "Administración"], "problema": ["Las aplicaciones de cuestionarios son muy populares, pero se discute si realmente ayudan a aprender o solo dan la sensación de dominio al recordar. La respuesta depende de cómo se usen y de qué preguntas contengan.", "Medirlo con un diseño sencillo permite usarlas con criterio."], "desarrollar": ["Elige dos temas de dificultad parecida: uno lo estudias con cuestionarios en una herramienta ya existente, con corrección inmediata y repaso de los fallos; el otro lo estudias releyendo. Una semana después, resuelve una prueba mixta con preguntas de recordar y de aplicar.", "Compara resultados por tipo de pregunta y analiza en qué casos el cuestionario ayudó más. Escribe recomendaciones para armar buenos cuestionarios."], "ampliaciones": [{"titulo": "Tipos de pregunta", "aporta": "compara preguntas de opción múltiple y de respuesta abierta."}, {"titulo": "Feedback", "aporta": "compara tener solo la nota o también la explicación."}, {"titulo": "Banco propio", "aporta": "arma un banco de preguntas para un curso."}], "objetivos": ["Comparar cuestionarios con otras formas de estudio.", "Analizar por tipo de pregunta.", "Medir el efecto del feedback.", "Redactar recomendaciones."], "habilidades": ["Diseño de pruebas.", "Análisis de datos.", "Pensamiento crítico.", "Redacción."], "herramientas": ["Una herramienta de cuestionarios ya existente.", "Hoja de cálculo.", "Material de estudio."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Usa herramientas que ya existan y cuyas condiciones de uso respetes; no subas datos de otras personas a plataformas sin su permiso.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión."], "otroSector": "El mismo diseño sirve para evaluar capacitaciones virtuales en el trabajo."}$a55sld$::jsonb,62),
('como-usar-la-inteligencia-artificial-como-apoyo-para-aprender-si','educacion',array['tecnologia']::text[],'¿Cómo usar la inteligencia artificial como apoyo para aprender sin depender de ella para resolver todo?','Diseña una guía de uso responsable de la IA para estudiar, que ayude a entender, practicar y verificar sin que la herramienta haga el trabajo por ti, y pruébala en tus propios cursos.','Guía','3 a 4 semanas',24,array['Inteligencia artificial','Aprendizaje autónomo']::text[],array['investigar','crear']::text[],'propios',NULL,'educacion ingenieria de sistemas ciencia de datos psicologia comunicaciones estadistica diseno administracion pensamiento critico. verificacion de informacion. autoobservacion. redaccion de guias. una herramienta de ia a tu eleccion. hoja de calculo. un editor de documentos.',$a56sld${"id": "como-usar-la-inteligencia-artificial-como-apoyo-para-aprender-si", "area": "educacion", "areas2": ["tecnologia"], "titulo": "¿Cómo usar la inteligencia artificial como apoyo para aprender sin depender de ella para resolver todo?", "resumen": "Diseña una guía de uso responsable de la IA para estudiar, que ayude a entender, practicar y verificar sin que la herramienta haga el trabajo por ti, y pruébala en tus propios cursos.", "tipo": "Guía", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Inteligencia artificial", "Aprendizaje autónomo"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Ingeniería de Sistemas", "Ciencia de Datos", "Psicología", "Comunicaciones", "Estadística", "Diseño", "Administración"], "problema": ["Las herramientas de IA pueden explicar temas, dar ejemplos o corregir, pero también pueden dar respuestas incorrectas o hacer que el estudiante deje de pensar. Cuando se copia la solución, se pierde el aprendizaje.", "Usarla con reglas claras la convierte en un apoyo y no en una muleta."], "desarrollar": ["Define usos que ayudan a aprender, como pedir explicaciones con ejemplos, generar preguntas de práctica o revisar tu razonamiento, y usos que lo estorban, como pedir la solución final. Pruébalos durante tres semanas en un curso y registra qué aprendiste y qué errores de la IA detectaste.", "Compara tu desempeño en una prueba sobre temas estudiados con apoyo de IA y sin él, y redacta una guía con reglas de uso, ejemplos de buenas instrucciones y un procedimiento para verificar respuestas."], "ampliaciones": [{"titulo": "Verificar respuestas", "aporta": "elabora un procedimiento para comprobar lo que dice la IA."}, {"titulo": "Instrucciones útiles", "aporta": "arma ejemplos de buenas instrucciones para aprender."}, {"titulo": "Políticas del curso", "aporta": "compara con las reglas de uso de IA de tu institución."}], "objetivos": ["Distinguir usos que ayudan y que estorban.", "Probarlos en un curso.", "Verificar respuestas.", "Redactar reglas de uso."], "habilidades": ["Pensamiento crítico.", "Verificación de información.", "Autoobservación.", "Redacción de guías."], "herramientas": ["Una herramienta de IA a tu elección.", "Hoja de cálculo.", "Un editor de documentos."], "lineamientos": ["Usa herramientas que ya existan y cuyas condiciones de uso respetes; no subas datos de otras personas a plataformas sin su permiso.", "Respeta las normas de tu institución sobre uso de IA y no la uses para entregar trabajo ajeno como propio.", "No ingreses datos personales ni material confidencial a herramientas de IA."], "otroSector": "La misma guía sirve para usar IA en el trabajo sin perder criterio ni exponer información."}$a56sld$::jsonb,63),
('disenando-una-actividad-educativa-que-combine-recursos-digitales','educacion',array['tecnologia']::text[],'Diseñando una actividad educativa que combine recursos digitales y ejercicios prácticos','Diseña una experiencia de aprendizaje que mezcle recursos digitales ya existentes, como videos, simuladores o cuestionarios, con ejercicios prácticos, y pruébala con un grupo pequeño.','Plan','3 a 4 semanas',24,array['Aprendizaje combinado','Diseño de actividades']::text[],array['crear']::text[],'ficticios',NULL,'educacion ingenieria de sistemas ciencia de datos psicologia comunicaciones estadistica diseno administracion diseno instruccional. seleccion de recursos. observacion. planificacion. recursos digitales gratuitos. un editor de documentos. una hoja de observacion.',$a57sld${"id": "disenando-una-actividad-educativa-que-combine-recursos-digitales", "area": "educacion", "areas2": ["tecnologia"], "titulo": "Diseñando una actividad educativa que combine recursos digitales y ejercicios prácticos", "resumen": "Diseña una experiencia de aprendizaje que mezcle recursos digitales ya existentes, como videos, simuladores o cuestionarios, con ejercicios prácticos, y pruébala con un grupo pequeño.", "tipo": "Plan", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Aprendizaje combinado", "Diseño de actividades"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Educación", "Ingeniería de Sistemas", "Ciencia de Datos", "Psicología", "Comunicaciones", "Estadística", "Diseño", "Administración"], "problema": ["Los recursos digitales por sí solos no siempre producen aprendizaje: hay que organizarlos con objetivos, práctica y retroalimentación. Muchas actividades son una lista de enlaces sin hilo conductor.", "Diseñar una secuencia clara con herramientas existentes aprovecha lo mejor de cada una."], "desarrollar": ["Elige un tema y define el objetivo de aprendizaje. Selecciona dos o tres recursos digitales gratuitos de buena calidad y diseña una secuencia: explicación, ejemplo, práctica guiada, práctica autónoma y cierre con una pregunta de aplicación.", "Prueba la actividad con tres a cinco personas, observa dónde se traban, mide con una breve prueba qué aprendieron y ajusta. Entrega la actividad como una ficha lista para reutilizar."], "ampliaciones": [{"titulo": "Versión sin conexión", "aporta": "adapta la actividad para quien no tenga internet."}, {"titulo": "Tiempo por etapa", "aporta": "ajusta los tiempos con lo observado."}, {"titulo": "Evaluación", "aporta": "diseña una rúbrica sencilla para la actividad."}], "objetivos": ["Definir un objetivo de aprendizaje.", "Elegir recursos digitales.", "Diseñar una secuencia.", "Probarla y ajustarla."], "habilidades": ["Diseño instruccional.", "Selección de recursos.", "Observación.", "Planificación."], "herramientas": ["Recursos digitales gratuitos.", "Un editor de documentos.", "Una hoja de observación."], "lineamientos": ["Usa herramientas que ya existan y cuyas condiciones de uso respetes; no subas datos de otras personas a plataformas sin su permiso.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión."], "otroSector": "El mismo diseño sirve para capacitaciones híbridas en empresas."}$a57sld$::jsonb,64),
('que-caracteristicas-hacen-que-un-curso-virtual-mantenga-la-atenc','educacion',array['tecnologia']::text[],'¿Qué características hacen que un curso virtual mantenga la atención de sus participantes?','Analiza qué rasgos de un curso virtual, como duración, interacción, ritmo o ejercicios, se relacionan con que la gente lo termine o lo abandone, y propone criterios para elegir o diseñar mejores cursos.','Análisis','3 semanas',22,array['Cursos virtuales','Atención']::text[],array['investigar','crear']::text[],'propios',NULL,'educacion ingenieria de sistemas ciencia de datos psicologia comunicaciones estadistica diseno administracion analisis comparativo. observacion. pensamiento critico. sintesis. plataformas gratuitas de cursos. hoja de calculo. un cuaderno de registro.',$a58sld${"id": "que-caracteristicas-hacen-que-un-curso-virtual-mantenga-la-atenc", "area": "educacion", "areas2": ["tecnologia"], "titulo": "¿Qué características hacen que un curso virtual mantenga la atención de sus participantes?", "resumen": "Analiza qué rasgos de un curso virtual, como duración, interacción, ritmo o ejercicios, se relacionan con que la gente lo termine o lo abandone, y propone criterios para elegir o diseñar mejores cursos.", "tipo": "Análisis", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Cursos virtuales", "Atención"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Ingeniería de Sistemas", "Ciencia de Datos", "Psicología", "Comunicaciones", "Estadística", "Diseño", "Administración"], "problema": ["Muchos se inscriben en cursos virtuales y pocos los terminan. Algunos duran demasiado, otros son monótonos o no dan oportunidad de practicar. No siempre es falta de voluntad: el diseño del curso influye.", "Identificar qué mantiene la atención ayuda a elegir y a diseñar cursos que se terminan."], "desarrollar": ["Elige tres cursos virtuales gratuitos que hayas hecho o empezado y analiza para cada uno: duración de cada lección, tipo de actividad, cantidad de ejercicios, interacción y si los terminaste. Recoge también la opinión de dos o tres compañeros.", "Compara los cursos, identifica rasgos asociados a la atención y al abandono y arma una lista de criterios para evaluar o diseñar un curso virtual."], "ampliaciones": [{"titulo": "Duración ideal", "aporta": "estima qué duración de lección sostiene mejor la atención."}, {"titulo": "Interacción", "aporta": "compara el efecto de foros, ejercicios y videos."}, {"titulo": "Seguimiento", "aporta": "propón recordatorios para completar un curso."}], "objetivos": ["Analizar cursos virtuales.", "Identificar rasgos de atención.", "Elaborar criterios.", "Aplicarlos a un caso."], "habilidades": ["Análisis comparativo.", "Observación.", "Pensamiento crítico.", "Síntesis."], "herramientas": ["Plataformas gratuitas de cursos.", "Hoja de cálculo.", "Un cuaderno de registro."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Describe rasgos del diseño y no ataques a instituciones o personas concretas.", "Usa herramientas que ya existan y cuyas condiciones de uso respetes; no subas datos de otras personas a plataformas sin su permiso."], "otroSector": "El mismo análisis sirve para diseñar capacitaciones virtuales en empresas."}$a58sld$::jsonb,65),
('como-influye-la-tecnologia-en-la-motivacion-para-aprender','educacion',array['tecnologia','sociedad']::text[],'¿Cómo influye la tecnología en la motivación para aprender?','Observa cómo cambia tu motivación al estudiar con distintas herramientas digitales, como aplicaciones, videos o juegos, y distingue entre la novedad inicial y la motivación sostenida.','Investigación','3 semanas',22,array['Motivación','Tecnología educativa']::text[],array['investigar']::text[],'propios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion autoobservacion. registro de datos. analisis simple. pensamiento critico. herramientas gratuitas de aprendizaje. hoja de calculo. un cuaderno de registro.',$a59sld${"id": "como-influye-la-tecnologia-en-la-motivacion-para-aprender", "area": "educacion", "areas2": ["tecnologia", "sociedad"], "titulo": "¿Cómo influye la tecnología en la motivación para aprender?", "resumen": "Observa cómo cambia tu motivación al estudiar con distintas herramientas digitales, como aplicaciones, videos o juegos, y distingue entre la novedad inicial y la motivación sostenida.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Motivación", "Tecnología educativa"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Una herramienta nueva suele entusiasmar los primeros días y luego se abandona. Algunas recursos mantienen el interés y otros solo entretienen. Se habla mucho de motivación, pero casi nunca se mide cómo cambia en el tiempo.", "Registrar tu experiencia ayuda a elegir herramientas que se sostengan."], "desarrollar": ["Durante tres semanas usa tres herramientas distintas para aprender un mismo tema, una por semana, y registra cada día tu motivación en una escala de 1 a 5, el tiempo que estudiaste y lo que lograste.", "Compara cómo evoluciona la motivación en cada semana, si cae después de los primeros días y si se relaciona con lo aprendido. Concluye qué características de las herramientas parecen sostener el interés."], "ampliaciones": [{"titulo": "Recompensas", "aporta": "analiza si puntos o insignias aumentan el esfuerzo o solo el entretenimiento."}, {"titulo": "Con compañeros", "aporta": "compara tus patrones con los de otras personas."}, {"titulo": "Hábitos", "aporta": "relaciona la motivación con la constancia."}], "objetivos": ["Registrar la motivación.", "Comparar herramientas.", "Distinguir novedad y constancia.", "Extraer conclusiones."], "habilidades": ["Autoobservación.", "Registro de datos.", "Análisis simple.", "Pensamiento crítico."], "herramientas": ["Herramientas gratuitas de aprendizaje.", "Hoja de cálculo.", "Un cuaderno de registro."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Usa herramientas que ya existan y cuyas condiciones de uso respetes; no subas datos de otras personas a plataformas sin su permiso.", "La motivación es subjetiva: preséntala como tu experiencia y no como un hecho general."], "otroSector": "El mismo estudio sirve para evaluar herramientas de trabajo o de entrenamiento físico."}$a59sld$::jsonb,66),
('comparando-recursos-digitales-y-recursos-fisicos-para-estudiar','educacion',array['tecnologia']::text[],'Comparando recursos digitales y recursos físicos para estudiar','Compara estudiar con libros, cuadernos y papel frente a hacerlo con pantallas y herramientas digitales, y mide comprensión, comodidad, distracciones y facilidad de repaso.','Investigación','3 semanas',20,array['Libros y pantallas','Recursos de estudio']::text[],array['investigar']::text[],'propios',NULL,'educacion ingenieria de sistemas ciencia de datos psicologia comunicaciones estadistica diseno administracion diseno de experimentos. autoobservacion. analisis de datos. redaccion. material en papel y digital. hoja de calculo. pruebas cortas propias.',$a60sld${"id": "comparando-recursos-digitales-y-recursos-fisicos-para-estudiar", "area": "educacion", "areas2": ["tecnologia"], "titulo": "Comparando recursos digitales y recursos físicos para estudiar", "resumen": "Compara estudiar con libros, cuadernos y papel frente a hacerlo con pantallas y herramientas digitales, y mide comprensión, comodidad, distracciones y facilidad de repaso.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 20, "etiquetas": ["Libros y pantallas", "Recursos de estudio"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Ingeniería de Sistemas", "Ciencia de Datos", "Psicología", "Comunicaciones", "Estadística", "Diseño", "Administración"], "problema": ["Hay quien jura por el papel y quien lo hace todo en digital. Cada formato tiene ventajas: lo físico distrae menos, lo digital se busca y se carga fácil. Pero pocas personas comparan con orden qué les resulta mejor.", "Medirlo permite combinar lo mejor de cada uno."], "desarrollar": ["Elige dos lecturas y dos conjuntos de ejercicios de dificultad parecida y estudia uno en papel y el otro en pantalla, midiendo tiempo, distracciones y comprensión con una prueba corta. Repite con otros temas.", "Compara los resultados y tu comodidad, anota ventajas y problemas de cada formato y elabora una guía de cuándo conviene cada uno según la actividad, como lectura, ejercicios o repaso."], "ampliaciones": [{"titulo": "Apuntes", "aporta": "compara apuntes a mano y apuntes digitales."}, {"titulo": "Lectura larga", "aporta": "compara leer un capítulo en papel y en pantalla."}, {"titulo": "Formato híbrido", "aporta": "prueba combinar lectura en papel y práctica en digital."}], "objetivos": ["Comparar formatos.", "Medir comprensión y distracción.", "Registrar ventajas y problemas.", "Elaborar una guía."], "habilidades": ["Diseño de experimentos.", "Autoobservación.", "Análisis de datos.", "Redacción."], "herramientas": ["Material en papel y digital.", "Hoja de cálculo.", "Pruebas cortas propias."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Usa herramientas que ya existan y cuyas condiciones de uso respetes; no subas datos de otras personas a plataformas sin su permiso.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión."], "otroSector": "La misma comparación sirve para decidir cómo documentar procesos en una empresa."}$a60sld$::jsonb,67),
('evaluando-la-utilidad-de-una-aplicacion-educativa-para-alcanzar','educacion',array['tecnologia']::text[],'Evaluando la utilidad de una aplicación educativa para alcanzar objetivos de aprendizaje','Evalúa una aplicación educativa con criterios claros, como objetivos de aprendizaje, calidad del contenido, retroalimentación y constancia, para saber si de verdad ayuda a aprender o solo entretiene.','Análisis','3 a 4 semanas',22,array['Aplicaciones educativas','Evaluación']::text[],array['investigar']::text[],'propios',NULL,'educacion ingenieria de sistemas ciencia de datos psicologia comunicaciones estadistica diseno administracion evaluacion de herramientas. medicion. pensamiento critico. redaccion de informes. una aplicacion educativa gratuita. hoja de calculo. una lista de criterios.',$a61sld${"id": "evaluando-la-utilidad-de-una-aplicacion-educativa-para-alcanzar", "area": "educacion", "areas2": ["tecnologia"], "titulo": "Evaluando la utilidad de una aplicación educativa para alcanzar objetivos de aprendizaje", "resumen": "Evalúa una aplicación educativa con criterios claros, como objetivos de aprendizaje, calidad del contenido, retroalimentación y constancia, para saber si de verdad ayuda a aprender o solo entretiene.", "tipo": "Análisis", "tiempo": "3 a 4 semanas", "horas": 22, "etiquetas": ["Aplicaciones educativas", "Evaluación"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Ingeniería de Sistemas", "Ciencia de Datos", "Psicología", "Comunicaciones", "Estadística", "Diseño", "Administración"], "problema": ["Hay miles de aplicaciones educativas, con reseñas que hablan de diseño y popularidad más que de aprendizaje real. Es difícil saber si realmente enseñan y si valen el tiempo invertido.", "Una evaluación con criterios claros ayuda a decidir con evidencia."], "desarrollar": ["Elige una aplicación educativa gratuita y define un objetivo de aprendizaje medible, como aprender cierta cantidad de vocabulario o resolver cierto tipo de problemas. Mide tu nivel antes, úsala durante tres semanas y mide de nuevo.", "Evalúa la aplicación con una lista de criterios: calidad del contenido, claridad, retroalimentación, motivación, publicidad y privacidad, y concluye si cumplió su objetivo y para quién la recomendarías."], "ampliaciones": [{"titulo": "Comparar dos aplicaciones", "aporta": "evalúa dos aplicaciones para el mismo objetivo."}, {"titulo": "Revisión de privacidad", "aporta": "analiza qué datos pide la aplicación."}, {"titulo": "Guía de selección", "aporta": "crea una lista para elegir aplicaciones educativas."}], "objetivos": ["Definir un objetivo medible.", "Evaluar una aplicación con criterios.", "Medir avances.", "Emitir una conclusión fundamentada."], "habilidades": ["Evaluación de herramientas.", "Medición.", "Pensamiento crítico.", "Redacción de informes."], "herramientas": ["Una aplicación educativa gratuita.", "Hoja de cálculo.", "Una lista de criterios."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Usa herramientas que ya existan y cuyas condiciones de uso respetes; no subas datos de otras personas a plataformas sin su permiso.", "Revisa la política de privacidad antes de usar la aplicación y no compartas datos personales innecesarios."], "otroSector": "La misma evaluación sirve para elegir herramientas de capacitación en una organización."}$a61sld$::jsonb,68),
('estilos-de-aprendizaje-mito-o-realidad','educacion',array['ciencias']::text[],'Estilos de aprendizaje: ¿mito o realidad?','Revisa qué dice la investigación sobre la idea de que cada persona aprende mejor de forma visual, auditiva o kinestésica, y pon a prueba esa creencia con tu propio aprendizaje.','Investigación','3 a 4 semanas',24,array['Estilos de aprendizaje','Evidencia']::text[],array['investigar']::text[],'publicos',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion lectura de fuentes cientificas. pensamiento critico. diseno de experimentos. comunicacion. buscadores academicos. hoja de calculo. un editor de documentos.',$a62sld${"id": "estilos-de-aprendizaje-mito-o-realidad", "area": "educacion", "areas2": ["ciencias"], "titulo": "Estilos de aprendizaje: ¿mito o realidad?", "resumen": "Revisa qué dice la investigación sobre la idea de que cada persona aprende mejor de forma visual, auditiva o kinestésica, y pon a prueba esa creencia con tu propio aprendizaje.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Estilos de aprendizaje", "Evidencia"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Se dice mucho que cada persona tiene un estilo de aprendizaje, y muchos materiales se diseñan con esa idea. Sin embargo, buena parte de la investigación ha encontrado poca evidencia de que enseñar según el supuesto estilo mejore los resultados.", "Revisar la evidencia y probarlo en la práctica ayuda a no tomar decisiones de estudio sobre una creencia popular."], "desarrollar": ["Busca en fuentes académicas y de divulgación confiables qué dice la investigación sobre los estilos de aprendizaje y qué alternativas se estudian, como adaptar el formato al contenido. Resume tres hallazgos con sus fuentes.", "Prueba en ti mismo: estudia dos temas con el formato que crees que es tu estilo y con otro formato, y mide con una prueba corta. Compara y discute si tu resultado apoya o no la idea."], "ampliaciones": [{"titulo": "Cuestionario de estilos", "aporta": "analiza qué tan confiable es un test de estilos de aprendizaje."}, {"titulo": "Formato según contenido", "aporta": "analiza si el formato ideal depende del tema y no de la persona."}, {"titulo": "Divulgación", "aporta": "prepara un material para explicar la evidencia a otros estudiantes."}], "objetivos": ["Revisar la evidencia.", "Contrastar con la propia experiencia.", "Distinguir mito y evidencia.", "Comunicar los hallazgos."], "habilidades": ["Lectura de fuentes científicas.", "Pensamiento crítico.", "Diseño de experimentos.", "Comunicación."], "herramientas": ["Buscadores académicos.", "Hoja de cálculo.", "Un editor de documentos."], "lineamientos": ["Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Presenta lo que dice la evidencia con cuidado y reconoce que el tema se sigue estudiando."], "otroSector": "El mismo ejercicio de contrastar creencias con evidencia sirve para cualquier consejo popular de productividad o de salud."}$a62sld$::jsonb,69),
('procrastinacion-que-la-provoca-y-que-estrategias-ayudan','educacion',array['salud']::text[],'Procrastinación: qué la provoca y qué estrategias ayudan','Registra cuándo postergas tareas, qué las vuelve difíciles de empezar y prueba estrategias como dividir la tarea o fijar un inicio mínimo, para ver cuáles reducen tu postergación.','Investigación','3 a 4 semanas',22,array['Procrastinación','Hábitos']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social autoobservacion. registro de datos. planificacion. cambio de habitos. hoja de calculo. un temporizador. cuaderno de registro.',$a63sld${"id": "procrastinacion-que-la-provoca-y-que-estrategias-ayudan", "area": "educacion", "areas2": ["salud"], "titulo": "Procrastinación: qué la provoca y qué estrategias ayudan", "resumen": "Registra cuándo postergas tareas, qué las vuelve difíciles de empezar y prueba estrategias como dividir la tarea o fijar un inicio mínimo, para ver cuáles reducen tu postergación.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 22, "etiquetas": ["Procrastinación", "Hábitos"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Postergar no siempre es pereza: muchas veces se evita una tarea que parece grande, confusa o aburrida. Las recomendaciones genéricas no funcionan para todos porque las causas son distintas.", "Identificar qué te frena en tu caso permite elegir estrategias que sí te sirven."], "desarrollar": ["Durante dos semanas anota cada tarea que postergas, qué sentías y cuánto tardaste en empezarla. Agrúpalas por tipo de causa, como tarea difícil, poco clara o poco interesante.", "Prueba durante dos semanas dos estrategias, por ejemplo dividir en pasos de diez minutos y empezar con un inicio mínimo, y compara cuánto tardas en empezar con y sin ellas. Resume qué te funcionó."], "ampliaciones": [{"titulo": "Causas de la postergación", "aporta": "clasifica las causas más frecuentes."}, {"titulo": "Fechas límite", "aporta": "compara el efecto de fechas propias intermedias."}, {"titulo": "Apoyo social", "aporta": "prueba avisar a un compañero cuándo vas a empezar."}], "objetivos": ["Registrar la postergación.", "Identificar causas.", "Probar estrategias.", "Comparar resultados."], "habilidades": ["Autoobservación.", "Registro de datos.", "Planificación.", "Cambio de hábitos."], "herramientas": ["Hoja de cálculo.", "Un temporizador.", "Cuaderno de registro."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Este proyecto no es una guía de salud: si la postergación te genera mucha angustia o afecta tu vida, busca apoyo profesional o en tu centro de estudios.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión."], "otroSector": "El mismo registro sirve para analizar la postergación de tareas en un trabajo."}$a63sld$::jsonb,70),
('como-analizar-un-examen-ya-calificado-para-aprender-de-tus-error','educacion',array[]::text[],'Cómo analizar un examen ya calificado para aprender de tus errores','Diseña un método para revisar un examen calificado, clasificar tus errores por tipo y causa y convertir el análisis en un plan de estudio para el siguiente examen.','Guía','2 semanas',18,array['Errores','Revisión de exámenes']::text[],array['investigar','crear']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social analisis de errores. autoevaluacion. planificacion. mejora continua. examenes calificados propios. hoja de calculo. un editor de documentos.',$a64sld${"id": "como-analizar-un-examen-ya-calificado-para-aprender-de-tus-error", "area": "educacion", "areas2": [], "titulo": "Cómo analizar un examen ya calificado para aprender de tus errores", "resumen": "Diseña un método para revisar un examen calificado, clasificar tus errores por tipo y causa y convertir el análisis en un plan de estudio para el siguiente examen.", "tipo": "Guía", "tiempo": "2 semanas", "horas": 18, "etiquetas": ["Errores", "Revisión de exámenes"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Muchos estudiantes miran la nota y guardan el examen sin revisarlo, perdiendo la mejor fuente de información sobre qué falló. Los errores pueden venir de no saber el tema, de descuidos o de mala gestión del tiempo, y cada causa exige una acción distinta.", "Analizar con método convierte un mal resultado en un plan."], "desarrollar": ["Toma dos exámenes calificados y clasifica cada error en categorías como concepto no entendido, error de cálculo, mala lectura de la pregunta, falta de tiempo o falta de estudio. Calcula cuántos puntos perdiste por categoría.", "Diseña una ficha de análisis para usar después de cada examen y un plan de acción para los errores más frecuentes. Pruébala con el siguiente examen y evalúa si ayudó."], "ampliaciones": [{"titulo": "Con compañeros", "aporta": "compara tus categorías de error con las de otros."}, {"titulo": "Banco de errores", "aporta": "arma un banco de errores y sus soluciones."}, {"titulo": "Examen de recuperación", "aporta": "diseña un mini examen con tus errores."}], "objetivos": ["Clasificar errores.", "Calcular su impacto.", "Diseñar una ficha de análisis.", "Aplicarla al siguiente examen."], "habilidades": ["Análisis de errores.", "Autoevaluación.", "Planificación.", "Mejora continua."], "herramientas": ["Exámenes calificados propios.", "Hoja de cálculo.", "Un editor de documentos."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Usa solo tus propios exámenes y respeta las reglas del curso sobre compartir evaluaciones."], "otroSector": "El mismo método sirve para revisar errores en proyectos, informes o entrevistas."}$a64sld$::jsonb,71),
('como-se-aprende-una-formula-o-una-demostracion-sin-memorizarla','educacion',array['ciencias']::text[],'Cómo se aprende una fórmula o una demostración sin memorizarla','Compara memorizar una fórmula con entender de dónde viene, y diseña una estrategia para aprender fórmulas y demostraciones a través de su sentido, ejemplos y casos límite.','Guía','3 semanas',22,array['Comprensión','Fórmulas']::text[],array['investigar','crear']::text[],'propios',NULL,'educacion biologia fisica quimica matematica diseno psicologia comunicaciones razonamiento cientifico. resolucion de problemas. autoevaluacion. redaccion de guias. libros del curso. hoja de calculo. ejercicios con soluciones.',$a65sld${"id": "como-se-aprende-una-formula-o-una-demostracion-sin-memorizarla", "area": "educacion", "areas2": ["ciencias"], "titulo": "Cómo se aprende una fórmula o una demostración sin memorizarla", "resumen": "Compara memorizar una fórmula con entender de dónde viene, y diseña una estrategia para aprender fórmulas y demostraciones a través de su sentido, ejemplos y casos límite.", "tipo": "Guía", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Comprensión", "Fórmulas"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Biología", "Física", "Química", "Matemática", "Diseño", "Psicología", "Comunicaciones"], "problema": ["En cursos de ciencias e ingeniería hay muchas fórmulas, y la tentación es memorizarlas. Pero se olvidan, se confunden y no sirven cuando el problema cambia un poco.", "Entender el sentido de una fórmula permite reconstruirla, aplicarla y detectar errores."], "desarrollar": ["Elige tres fórmulas de un curso. De una, memoriza la expresión; de otra, estudia su origen y significado; de la tercera, practica con casos y valores límite. Una semana después, resuelve problemas variados que las usen.", "Compara resultados y errores, y arma una guía con pasos para estudiar una fórmula entendiéndola: de dónde viene, qué significan sus partes, qué pasa en casos extremos y cómo verificar un resultado."], "ampliaciones": [{"titulo": "Fórmulas relacionadas", "aporta": "arma un mapa de relaciones entre fórmulas."}, {"titulo": "Chequeo dimensional", "aporta": "usa unidades para detectar errores."}, {"titulo": "Demostraciones", "aporta": "aplica la estrategia a una demostración."}], "objetivos": ["Comparar memorizar y entender.", "Medir el rendimiento en problemas nuevos.", "Elaborar una guía.", "Aplicarla."], "habilidades": ["Razonamiento científico.", "Resolución de problemas.", "Autoevaluación.", "Redacción de guías."], "herramientas": ["Libros del curso.", "Hoja de cálculo.", "Ejercicios con soluciones."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Verifica todas las fórmulas y demostraciones en fuentes confiables antes de usarlas."], "otroSector": "El mismo enfoque sirve para aprender procedimientos en contabilidad, programación o química."}$a65sld$::jsonb,72)
